import React from 'react';import {createRoot} from 'react-dom/client';
const nativeFetch=window.fetch;Object.assign(window,{hourlyCalls:[]});window.fetch=async(input,init)=>{if(String(input).endsWith('/performance-hourly')){const body=JSON.parse(String(init?.body));(window as unknown as {hourlyCalls:unknown[]}).hourlyCalls.push(body);return Response.json({result:{status:'observed',source:'naver_stats',targetId:body.targetId,day:body.since,hours:[{hour:17,impressions:62,clicks:3,cost:1399,purchases:0,revenue:0,averageCpc:466.333},{hour:18,impressions:64,clicks:5,cost:2419,purchases:1,revenue:28500,averageCpc:483.8}]}})}return nativeFetch(input,init)};
void import('../../src/components/store/ad-performance-panel').then(({AdPerformancePanel})=>createRoot(document.getElementById('root')!).render(<AdPerformancePanel/>));
